17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Map;
25	import java.util.regex.Pattern;
26	
27	import org.slf4j.Logger;
28	import org.slf4j.LoggerFactory;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /** Dedicated audit logger for owner lifecycle side-effects. */
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    /**
67	     * Pragmatic check for a syntactically valid email address: a non-empty local
68	     * part, a single '@', and a domain with at least one dot-separated label.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
72	
73	    /**
74	     * Common street-type abbreviations expanded during address normalization,
75	     * keyed by their upper-cased form.
76	     */
77	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
78	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
79	
80	    /**
81	     * Required national-number length keyed by E.164 country calling code: a
82	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
83	     * (NANP) number carries 10. A number whose country code is listed here must have
84	     * exactly the mandated number of national digits.
85	     */
86	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
87	        Map.of("61", 9, "1", 10);
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        // Validate & normalize the optional email; reject the create when it is present but invalid.
136	        if (!normalizeEmail(ownerFieldsDto)) {
137	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
138	        }
139	        // Reject the create when another owner already uses this email (compared case-insensitively
140	        // by lower-cased email). The DTO email is already normalized to its lower-cased form here.
141	        String normalizedEmail = ownerFieldsDto.getEmail();
142	        if (normalizedEmail != null) {
143	            boolean emailInUse = this.clinicService.findAllOwners().stream()
144	                .map(Owner::getEmail)
145	                .filter(existing -> existing != null)
146	                .map(existing -> existing.toLowerCase(Locale.ROOT))
147	                .anyMatch(normalizedEmail::equals);
148	            if (emailInUse) {
149	                return new ResponseEntity<>(HttpStatus.CONFLICT);
150	            }
151	        }
152	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
153	        // abbreviations) and store the normalized form back on the DTO so it is what gets
154	        // persisted and compared. Reject the create when the address is blank once normalized.
155	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
156	        if (canonicalAddress.isBlank()) {
157	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
158	        }
159	        ownerFieldsDto.setAddress(canonicalAddress);
160	        // Reject the create when the owner's city is already at capacity, i.e. it already
161	        // contains 50 or more owners (compared case-insensitively).
162	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
163	            return new ResponseEntity<>(HttpStatus.CONFLICT);
164	        }
165	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
166	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
167	        if (normalizedTelephone == null) {
168	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
169	        }
170	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
171	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
172	            .map(Owner::getTelephone)
173	            .map(OwnerRestControllerV1::toE164)
174	            .filter(existing -> existing != null)
175	            .anyMatch(normalizedTelephone::equals);
176	        if (telephoneInUse) {
177	            return new ResponseEntity<>(HttpStatus.CONFLICT);
178	        }
179	        // Reject the create when another owner already shares this owner's last name and address
180	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
181	        // sharing a household.
182	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
183	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
184	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
185	            boolean householdInUse = this.clinicService.findAllOwners().stream()
186	                .anyMatch(existing ->
187	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
188	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
189	            if (householdInUse) {
190	                return new ResponseEntity<>(HttpStatus.CONFLICT);
191	            }
192	        }
193	        // Determine the effective registration date — the value supplied on the request, or the
194	        // server's current date when none was supplied — and roll it forward to the next business
195	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
196	        // registration date (membership-number year segment, per-day create-limit) uses this
197	        // adjusted date.
198	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
199	        if (registrationDate == null) {
200	            registrationDate = LocalDate.now();
201	        }
202	        registrationDate = toBusinessDay(registrationDate);
203	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
204	        // owners have already been registered on this (adjusted) business day.
205	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
206	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
207	        }
208	        ownerFieldsDto.setTelephone(normalizedTelephone);
209	        HttpHeaders headers = new HttpHeaders();
210	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
211	        owner.setRegistrationDate(registrationDate);
212	        // Assign the customer code as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three
213	        // letters of the city, the upper-cased first three letters of the last name, and a
214	        // per-city 4-digit sequence one greater than the number of owners already in that city.
215	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
216	        // Record how many existing owners already share this owner's first and last name
217	        // (compared case-insensitively) at the moment before this owner is created.
218	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
219	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
220	        // registered on this (adjusted) business day before this owner is created.
221	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
222	        // Record the size of this owner's household after this create: the number of existing
223	        // owners sharing the same household (matching last name and address) plus this owner.
224	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
225	        this.clinicService.saveOwner(owner);
226	        // Emit an audit line recording the new owner's id, customer code, registration date
227	        // and membership level.
228	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
229	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
230	            ownerMapper.membershipLevel(owner));
231	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
232	        headers.setLocation(UriComponentsBuilder.newInstance()
233	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
234	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
235	    }
236	
237	    /**
238	     * Validate and normalize the optional owner email in place.
239	     *
240	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
241	     * When present it must be a syntactically valid address; a valid address is
242	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
243	     * present but syntactically invalid, so the caller can reject with 400.
244	     */
245	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
246	        String email = ownerFieldsDto.getEmail();
247	        if (email == null || email.isBlank()) {
248	            ownerFieldsDto.setEmail(null);
249	            return true;
250	        }
251	        String normalized = email.trim().toLowerCase(Locale.ROOT);
252	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
253	            return false;
254	        }
255	        ownerFieldsDto.setEmail(normalized);
256	        return true;
257	    }
258	
259	    /**
260	     * Normalize an owner address: trim, collapse each run of whitespace to a single
261	     * space, upper-case, and expand common street-type abbreviations
262	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
263	     * A {@code null} value normalizes to the empty string.
264	     */
265	    private static String normalizeAddress(String value) {
266	        if (value == null) {
267	            return "";
268	        }
269	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
270	        if (collapsed.isEmpty()) {
271	            return "";
272	        }
273	        String[] tokens = collapsed.split(" ");
274	        StringBuilder sb = new StringBuilder(collapsed.length());
275	        for (int i = 0; i < tokens.length; i++) {
276	            if (i > 0) {
277	                sb.append(' ');
278	            }
279	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
280	        }
281	        return sb.toString();
282	    }
283	
284	    /**
285	     * Normalize an owner household field (last name or address) for duplicate detection:
286	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
287	     * A {@code null} value normalizes to the empty string.
288	     */
289	    private static String normalizeHouseholdKey(String value) {
290	        if (value == null) {
291	            return "";
292	        }
293	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
294	    }
295	
296	    /**
297	     * Normalize a telephone number to E.164 form.
298	     *
299	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
300	     * explicit leading {@code '+'} and country code it is kept; otherwise the
301	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
302	     * dropped from the national digits. The result must contain 8 to 15 digits
303	     * after the {@code '+'}, and — for a recognised country calling code — exactly
304	     * the national-number length that code mandates ({@code '+61'} => 9 national
305	     * digits, {@code '+1'} => 10).
306	     *
307	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
308	     *         the input is absent or cannot form a valid E.164 number.
309	     */
310	    private static String toE164(String raw) {
311	        if (raw == null) {
312	            return null;
313	        }
314	        String trimmed = raw.trim();
315	        boolean hasCountryCode = trimmed.startsWith("+");
316	        // Strip spaces, dashes and brackets.
317	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
318	        String digits;
319	        if (hasCountryCode) {
320	            // Keep the explicit country code; drop the leading '+' for validation.
321	            digits = stripped.substring(1);
322	        } else {
323	            // No country code: assume '+61' and drop a single leading '0'.
324	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
325	            digits = "61" + national;
326	        }
327	        if (!digits.matches("\\d{8,15}")) {
328	            return null;
329	        }
330	        // For a recognised country calling code, enforce the exact national-number length it
331	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
332	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
333	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
334	                .sorted((a, b) -> b.length() - a.length()).toList()) {
335	            if (digits.startsWith(countryCode)) {
336	                int nationalLength = digits.length() - countryCode.length();
337	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
338	                    return null;
339	                }
340	                break;
341	            }
342	        }
343	        return "+" + digits;
344	    }
345	
346	    /**
347	     * Build the next customer code, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}.
348	     *
349	     * <p>{@code CITY3} is the upper-cased first three letters of {@code city} and
350	     * {@code LAST3} the upper-cased first three letters of {@code lastName} (fewer if
351	     * the value is shorter). {@code NNNN} is a per-city 4-digit zero-padded sequence
352	     * equal to one more than the number of owners already in that city
353	     * (e.g. {@code 'SYD-SMI-0007'}).
354	     */
355	    /**
356	     * Count the existing owners whose first and last name match the given names,
357	     * compared case-insensitively. Used to record an owner's namesake count at the
358	     * moment before it is created.
359	     */
360	    private int countNamesakes(String firstName, String lastName) {
361	        return (int) this.clinicService.findAllOwners().stream()
362	            .filter(existing -> existing.getFirstName() != null
363	                && existing.getFirstName().equalsIgnoreCase(firstName)
364	                && existing.getLastName() != null
365	                && existing.getLastName().equalsIgnoreCase(lastName))
366	            .count();
367	    }
368	
369	    /**
370	     * Count the existing owners in the same household as the given last name and address
371	     * (compared after household-key normalization). Used, together with the owner being
372	     * created, to derive the household size recorded on the owner.
373	     */
374	    private int countHouseholdMembers(String lastName, String address) {
375	        String normalizedLastName = normalizeHouseholdKey(lastName);
376	        String normalizedAddress = normalizeHouseholdKey(address);
377	        return (int) this.clinicService.findAllOwners().stream()
378	            .filter(existing ->
379	                normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
380	                    && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress))
381	            .count();
382	    }
383	
384	    private String nextCustomerCode(String city, String lastName) {
385	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
386	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
387	        int sequence = countOwnersInCity(city) + 1;
388	        return String.format("%s-%s-%04d", city3, last3, sequence);
389	    }
390	
391	    /**
392	     * Count the existing owners located in the given city, compared case-insensitively.
393	     * Used to derive the per-city 4-digit sequence in the customer code.
394	     */
395	    private int countOwnersInCity(String city) {
396	        return (int) this.clinicService.findAllOwners().stream()
397	            .filter(existing -> existing.getCity() != null
398	                && existing.getCity().equalsIgnoreCase(city))
399	            .count();
400	    }
401	
402	    /**
403	     * Count the existing owners whose registration date is the given (adjusted business) date.
404	     * Used to enforce the per-day sign-up limit.
405	     */
406	    private int countOwnersRegisteredOn(LocalDate date) {
407	        return (int) this.clinicService.findAllOwners().stream()
408	            .filter(existing -> date.equals(existing.getRegistrationDate()))
409	            .count();
410	    }
411	
412	    /**
413	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
414	     * the following Monday; a weekday is returned unchanged.
415	     */
416	    private static LocalDate toBusinessDay(LocalDate date) {
417	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
418	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
419	            date = date.plusDays(1);
420	        }
421	        return date;
422	    }
423	
424	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
425	    @Override
426	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
427	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
428	        if (currentOwner == null) {
429	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
430	        }
431	        if (!normalizeEmail(ownerFieldsDto)) {
432	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
433	        }
434	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
435	        if (normalizedTelephone == null) {
436	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
437	        }
438	        currentOwner.setAddress(ownerFieldsDto.getAddress());
439	        currentOwner.setCity(ownerFieldsDto.getCity());
440	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
441	        currentOwner.setLastName(ownerFieldsDto.getLastName());
442	        currentOwner.setTelephone(normalizedTelephone);
443	        currentOwner.setEmail(ownerFieldsDto.getEmail());
444	        this.clinicService.saveOwner(currentOwner);
445	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
446	    }
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Transactional
450	    @Override
451	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
452	        Owner owner = this.clinicService.findOwnerById(ownerId);
453	        if (owner == null) {
454	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
455	        }
456	        this.clinicService.deleteOwner(owner);
457	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
458	    }
459	
460	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
461	    @Override
462	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
463	        Owner owner = this.clinicService.findOwnerById(ownerId);
464	        if (owner == null) {
465	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
466	        }
467	        HttpHeaders headers = new HttpHeaders();
468	        Pet pet = petMapper.toPet(petFieldsDto);
469	        owner.setId(ownerId);
470	        pet.setOwner(owner);
471	        pet.getType().setName(null);
472	        this.clinicService.savePet(pet);
473	        PetDto petDto = petMapper.toPetDto(pet);
474	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
475	            .buildAndExpand(pet.getId()).toUri());
476	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
477	    }
478	
479	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
480	    @Override
481	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
482	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
483	        if (currentOwner != null) {
484	            Pet currentPet = this.clinicService.findPetById(petId);
485	            if (currentPet != null) {
486	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
487	                currentPet.setName(petFieldsDto.getName());
488	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
489	                this.clinicService.savePet(currentPet);
490	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
491	            }
492	        }
493	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
494	    }
495	
496	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
497	    @Override
498	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
499	        HttpHeaders headers = new HttpHeaders();
500	        Visit visit = visitMapper.toVisit(visitFieldsDto);
501	        Pet pet = new Pet();
502	        pet.setId(petId);
503	        visit.setPet(pet);
504	        this.clinicService.saveVisit(visit);
505	        VisitDto visitDto = visitMapper.toVisitDto(visit);
506	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
507	            .buildAndExpand(visit.getId()).toUri());
508	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
509	    }
510	
511	
512	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
513	    @Override
514	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
515	        Owner owner = this.clinicService.findOwnerById(ownerId);
516	        if (owner != null) {
517	            Pet pet = owner.getPet(petId);
518	            if (pet != null) {
519	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
520	            }
521	        }
522	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
523	    }
524	}
